import React, { useState } from 'react';
import './HouseDetailsForm.css'; // Ensure this file contains the CSS for styling

function HouseDetailsForm() {
  const [formData, setFormData] = useState({
    houseName: '',
    ownerName: '',
    countryCode: '',
    mobileNumber: '',
    plotAddress: '',
    plotSize: '',
    numberOfFloors: '',
    totalFloorArea: '',
    houseType: '',
    numberOfBedrooms: '',
    numberOfBathrooms: '',
    numberOfLivingRooms: '',
    numberOfKitchens: '',
    roomDetails: '',
    houseStyle: '',
    heatingCoolingSystem: '',
    securitySystemDetails: '',
    emergencyExit: '',
    constructionTimelineFrom: '',
    constructionTimelineTo: '',
    paymentSchedule: '',
    buildingPermitDetails: '',
    specialRequirements: '',
    futureExpansionPlans: ''
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const validate = () => {
    const newErrors = {};

    if (!formData.houseName) newErrors.houseName = 'House Name is required.';
    if (!formData.ownerName) newErrors.ownerName = 'Owner Name is required.';
    if (!formData.countryCode.match(/^\d{1,2}$/)) newErrors.countryCode = 'Country Code must be 1 or 2 digits.';
    if (!formData.mobileNumber.match(/^[1-9]\d{9}$/)) newErrors.mobileNumber = 'Mobile Number must be 10 digits starting from 1-9.';
    if (!formData.plotAddress) newErrors.plotAddress = 'Plot Address is required.';
    if (!formData.plotSize || isNaN(formData.plotSize)) newErrors.plotSize = 'Plot Size must be a number.';
    if (!formData.numberOfFloors || isNaN(formData.numberOfFloors)) newErrors.numberOfFloors = 'Number of Floors must be a number.';
    if (!formData.totalFloorArea || isNaN(formData.totalFloorArea)) newErrors.totalFloorArea = 'Total Floor Area must be a number.';
    if (!formData.houseType) newErrors.houseType = 'House Type is required.';
    if (!formData.numberOfBedrooms || isNaN(formData.numberOfBedrooms)) newErrors.numberOfBedrooms = 'Number of Bedrooms must be a number.';
    if (!formData.numberOfBathrooms || isNaN(formData.numberOfBathrooms)) newErrors.numberOfBathrooms = 'Number of Bathrooms must be a number.';
    if (!formData.numberOfLivingRooms || isNaN(formData.numberOfLivingRooms)) newErrors.numberOfLivingRooms = 'Number of Living Rooms must be a number.';
    if (!formData.numberOfKitchens || isNaN(formData.numberOfKitchens)) newErrors.numberOfKitchens = 'Number of Kitchens must be a number.';
    if (!formData.roomDetails) newErrors.roomDetails = 'Details of the Room are required.';
    if (!formData.houseStyle) newErrors.houseStyle = 'House Style is required.';
    if (!formData.heatingCoolingSystem) newErrors.heatingCoolingSystem = 'Heating and Cooling System is required.';
    if (!formData.securitySystemDetails) newErrors.securitySystemDetails = 'Security System Details are required.';
    if (!formData.emergencyExit || isNaN(formData.emergencyExit)) newErrors.emergencyExit = 'Emergency Exit must be a number.';
    if (!formData.constructionTimelineFrom || !formData.constructionTimelineTo) newErrors.constructionTimeline = 'Construction Timeline is required.';
    if (!formData.paymentSchedule) newErrors.paymentSchedule = 'Payment Schedule is required.';
    if (!formData.buildingPermitDetails) newErrors.buildingPermitDetails = 'Building Permit Details are required.';
    if (!formData.specialRequirements) newErrors.specialRequirements = 'Special Requirements are required.';
    if (!formData.futureExpansionPlans) newErrors.futureExpansionPlans = 'Future Expansion Plans are required.';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validate()) {
      console.log('Form Data:', formData);
      // Add form submission logic here
    }
  };

  return (
    <form onSubmit={handleSubmit} className="house-details-form">
      <div className="form-group">
        <label>House Name:</label>
        <input
          type="text"
          name="houseName"
          maxLength="50"
          value={formData.houseName}
          onChange={handleChange}
        />
        {errors.houseName && <span className="error">{errors.houseName}</span>}
      </div>

      <div className="form-group">
        <label>Owner Name:</label>
        <input
          type="text"
          name="ownerName"
          maxLength="50"
          value={formData.ownerName}
          onChange={handleChange}
        />
        {errors.ownerName && <span className="error">{errors.ownerName}</span>}
      </div>

      <div className="form-group">
        <label>Country Code:</label>
        <input
          type="text"
          name="countryCode"
          maxLength="2"
          pattern="\d{1,2}"
          value={formData.countryCode}
          onChange={handleChange}
        />
        {errors.countryCode && <span className="error">{errors.countryCode}</span>}
      </div>

      <div className="form-group">
        <label>Mobile Number:</label>
        <input
          type="text"
          name="mobileNumber"
          maxLength="10"
          pattern="[1-9]\d{9}"
          value={formData.mobileNumber}
          onChange={handleChange}
        />
        {errors.mobileNumber && <span className="error">{errors.mobileNumber}</span>}
      </div>

      <div className="form-group">
        <label>Plot Address:</label>
        <input
          type="text"
          name="plotAddress"
          maxLength="60"
          value={formData.plotAddress}
          onChange={handleChange}
        />
        {errors.plotAddress && <span className="error">{errors.plotAddress}</span>}
      </div>

      <div className="form-group">
        <label>Plot Size:</label>
        <input
          type="number"
          name="plotSize"
          value={formData.plotSize}
          onChange={handleChange}
        />
        {errors.plotSize && <span className="error">{errors.plotSize}</span>}
      </div>

      <div className="form-group">
        <label>Number of Floors:</label>
        <input
          type="number"
          name="numberOfFloors"
          value={formData.numberOfFloors}
          onChange={handleChange}
        />
        {errors.numberOfFloors && <span className="error">{errors.numberOfFloors}</span>}
      </div>

      <div className="form-group">
        <label>Total Floor Area:</label>
        <input
          type="range"
          name="totalFloorArea"
          min="500"
          max="5000"
          value={formData.totalFloorArea}
          onChange={handleChange}
        />
        {errors.totalFloorArea && <span className="error">{errors.totalFloorArea}</span>}
      </div>

      <div className="form-group">
        <label>House Type:</label>
        <div>
          <label>
            <input
              type="radio"
              name="houseType"
              value="Bungalow"
              checked={formData.houseType === 'Bungalow'}
              onChange={handleChange}
            />
            Bungalow
          </label>
          <label>
            <input
              type="radio"
              name="houseType"
              value="Apartment"
              checked={formData.houseType === 'Apartment'}
              onChange={handleChange}
            />
            Apartment
          </label>
          <label>
            <input
              type="radio"
              name="houseType"
              value="Duplex"
              checked={formData.houseType === 'Duplex'}
              onChange={handleChange}
            />
            Duplex
          </label>
          <label>
            <input
              type="radio"
              name="houseType"
              value="Villa"
              checked={formData.houseType === 'Villa'}
              onChange={handleChange}
            />
            Villa
          </label>
        </div>
        {errors.houseType && <span className="error">{errors.houseType}</span>}
      </div>

      <div className="form-group">
        <label>Number of Bedrooms:</label>
        <input
          type="number"
          name="numberOfBedrooms"
          value={formData.numberOfBedrooms}
          onChange={handleChange}
        />
        {errors.numberOfBedrooms && <span className="error">{errors.numberOfBedrooms}</span>}
      </div>

      <div className="form-group">
        <label>Number of Bathrooms:</label>
        <input
          type="number"
          name="numberOfBathrooms"
          value={formData.numberOfBathrooms}
          onChange={handleChange}
        />
        {errors.numberOfBathrooms && <span className="error">{errors.numberOfBathrooms}</span>}
      </div>

      <div className="form-group">
        <label>Number of Living Rooms:</label>
        <input
          type="number"
          name="numberOfLivingRooms"
          value={formData.numberOfLivingRooms}
          onChange={handleChange}
        />
        {errors.numberOfLivingRooms && <span className="error">{errors.numberOfLivingRooms}</span>}
      </div>

      <div className="form-group">
        <label>Number of Kitchens:</label>
        <input
          type="number"
          name="numberOfKitchens"
          value={formData.numberOfKitchens}
          onChange={handleChange}
        />
        {errors.numberOfKitchens && <span className="error">{errors.numberOfKitchens}</span>}
      </div>

      <div className="form-group">
        <label>Details of the Room:</label>
        <input
          type="text"
          name="roomDetails"
          value={formData.roomDetails}
          onChange={handleChange}
        />
        {errors.roomDetails && <span className="error">{errors.roomDetails}</span>}
      </div>

      <div className="form-group">
        <label>Style of House:</label>
        <div>
          <label>
            <input
              type="radio"
              name="houseStyle"
              value="Modern"
              checked={formData.houseStyle === 'Modern'}
              onChange={handleChange}
            />
            Modern
          </label>
          <label>
            <input
              type="radio"
              name="houseStyle"
              value="Traditional"
              checked={formData.houseStyle === 'Traditional'}
              onChange={handleChange}
            />
            Traditional
          </label>
          <label>
            <input
              type="radio"
              name="houseStyle"
              value="Contemporary"
              checked={formData.houseStyle === 'Contemporary'}
              onChange={handleChange}
            />
            Contemporary
          </label>
        </div>
        {errors.houseStyle && <span className="error">{errors.houseStyle}</span>}
      </div>

      <div className="form-group">
        <label>Heating and Cooling Systems:</label>
        <div>
          <label>
            <input
              type="radio"
              name="heatingCoolingSystem"
              value="Central"
              checked={formData.heatingCoolingSystem === 'Central'}
              onChange={handleChange}
            />
            Central
          </label>
          <label>
            <input
              type="radio"
              name="heatingCoolingSystem"
              value="Individual"
              checked={formData.heatingCoolingSystem === 'Individual'}
              onChange={handleChange}
            />
            Individual
          </label>
        </div>
        {errors.heatingCoolingSystem && <span className="error">{errors.heatingCoolingSystem}</span>}
      </div>

      <div className="form-group">
        <label>Security System Details:</label>
        <input
          type="text"
          name="securitySystemDetails"
          value={formData.securitySystemDetails}
          onChange={handleChange}
        />
        {errors.securitySystemDetails && <span className="error">{errors.securitySystemDetails}</span>}
      </div>

      <div className="form-group">
        <label>Emergency Exit:</label>
        <input
          type="number"
          name="emergencyExit"
          value={formData.emergencyExit}
          onChange={handleChange}
        />
        {errors.emergencyExit && <span className="error">{errors.emergencyExit}</span>}
      </div>

      <div className="form-group">
        <label>Construction Timeline:</label>
        <input
          type="date"
          name="constructionTimelineFrom"
          value={formData.constructionTimelineFrom}
          onChange={handleChange}
        />
        <input
          type="date"
          name="constructionTimelineTo"
          value={formData.constructionTimelineTo}
          onChange={handleChange}
        />
        {errors.constructionTimeline && <span className="error">{errors.constructionTimeline}</span>}
      </div>

      <div className="form-group">
        <label>Payment Schedule:</label>
        <div>
          <label>
            <input
              type="radio"
              name="paymentSchedule"
              value="Full Payment"
              checked={formData.paymentSchedule === 'Full Payment'}
              onChange={handleChange}
            />
            Full Payment
          </label>
          <label>
            <input
              type="radio"
              name="paymentSchedule"
              value="Installments"
              checked={formData.paymentSchedule === 'Installments'}
              onChange={handleChange}
            />
            Installments
          </label>
        </div>
        {errors.paymentSchedule && <span className="error">{errors.paymentSchedule}</span>}
      </div>

      <div className="form-group">
        <label>Building Permit Details:</label>
        <input
          type="text"
          name="buildingPermitDetails"
          value={formData.buildingPermitDetails}
          onChange={handleChange}
        />
        {errors.buildingPermitDetails && <span className="error">{errors.buildingPermitDetails}</span>}
      </div>

      <div className="form-group">
        <label>Special Requirements:</label>
        <input
          type="text"
          name="specialRequirements"
          value={formData.specialRequirements}
          onChange={handleChange}
        />
        {errors.specialRequirements && <span className="error">{errors.specialRequirements}</span>}
      </div>

      <div className="form-group">
        <label>Future Expansion Plans:</label>
        <input
          type="text"
          name="futureExpansionPlans"
          value={formData.futureExpansionPlans}
          onChange={handleChange}
        />
        {errors.futureExpansionPlans && <span className="error">{errors.futureExpansionPlans}</span>}
      </div>

      <button type="submit">Submit</button>
    </form>
  );
}

export default HouseDetailsForm;
